sparql:
PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
# id: absorption_coefficient_per_paper
SELECT ?paper ?paperLabel ?absorptionCoefficient ?absorptionCoefficientLabel ?numericValue ?unit ?unitLabel
WHERE {
  # Select the paper and its template instance (contribution)
  ?paper orkgp:P31 ?paperContribution .
  ?paperContribution orkgp:P161031 ?hop1 .
  ?hop1 orkgp:P161034 ?contribution .
  ?contribution a orkgc:C117033 .
  # Paper title
  ?paper rdfs:label ?paperLabel .
  # Absorption coefficient of the contribution
  OPTIONAL {
    ?contribution orkgp:P161026 ?absorptionCoefficient .
    OPTIONAL { ?absorptionCoefficient rdfs:label ?absorptionCoefficientLabel }
    # Quantity value node of the absorption coefficient
    OPTIONAL {
      ?absorptionCoefficient orkgp:P45073 ?qv .
      OPTIONAL { ?qv orkgp:P45075 ?numericValue }
      OPTIONAL { ?qv orkgp:P45076 ?unit . OPTIONAL { ?unit rdfs:label ?unitLabel } }
    }
  }
}
ORDER BY ?paperLabel

PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
# id: evaluation_per_paper_retrieval_system
SELECT ?paper ?paperLabel ?evaluation ?evaluationLabel ?metric ?metricLabel ?value ?unit ?unitLabel
WHERE {
  # Paper and its Retrieval system contribution
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C77004 .
  # Paper title
  ?paper rdfs:label ?paperLabel .
  # Evaluation reported by the paper
  ?contribution orkgp:P34 ?evaluation .
  OPTIONAL { ?evaluation rdfs:label ?evaluationLabel }
  # Metric of the evaluation
  OPTIONAL {
    ?evaluation orkgp:HAS_METRIC ?metric .
    OPTIONAL { ?metric rdfs:label ?metricLabel }
  }
  # Value and unit of the evaluation
  OPTIONAL {
    ?evaluation orkgp:HAS_VALUE ?valueNode .
    OPTIONAL { ?valueNode orkgp:P45075 ?value }
    OPTIONAL { ?valueNode orkgp:P45076 ?unit . OPTIONAL { ?unit rdfs:label ?unitLabel } }
  }
}
ORDER BY ?paperLabel
